/bin/zsh -lc "node - <<'NODE'
const fs=require('fs');
for (const tier of [100,500,2200]) {
 const full=JSON.parse(fs.readFileSync("'`docs/acceptance/t2208-real-collaboration-baseline/evidence/raw/real-${tier}/api-visible_full.json`,'"'utf8')).body;
 const res=JSON.parse(fs.readFileSync("'`docs/acceptance/t2208-real-collaboration-baseline/evidence/raw/real-${tier}/result.json`,'"'utf8'));
 const har=JSON.parse(fs.readFileSync("'`docs/acceptance/t2208-real-collaboration-baseline/evidence/raw/real-${tier}/network.har`,'"'utf8'));
 const entries=har.log.entries.filter(e=>e.request.url.includes('/api/orgs/')&&e.request.url.includes('collaboration-effects?')&&e.request.url.includes("'`agent_ref=${encodeURIComponent(res.filters.agent_ref)}`)&&e.response.status===200&&e.response.content.text.trim().startsWith('"'{'));
 const filtered=JSON.parse(entries.at(-1).response.content.text);
 const aIds=new Set(filtered.graph.edges.map(e=>e.id));
 for (const pred of ['direct','agent_field']) {
  let arr=full.graph.edges.filter(e=> pred==='direct' ? (e.source===res.filters.agent_ref||e.target===res.filters.agent_ref) : (e.source===res.filters.agent_ref||e.target===res.filters.agent_ref||e.relation_type==='plan_task'||e.relation_type==='project_plan'||e.relation_type==='task_agent'));
  const ids=new Set(arr.map(e=>e.id));
  console.log(tier,pred,arr.length,'missing', [...aIds].filter(x=>"'!ids.has(x)).length, '"'extra', [...ids].filter(x=>"'!aIds.has(x)).length);
 }
 console.log('"'actual relations', filtered.graph.edges.reduce((m,e)=>(m[e.relation_type]=(m[e.relation_type]||0)+1,m),{}));
 console.log('sample relations full first actual', filtered.graph.edges.slice(0,10).map(e=>[e.id,e.relation_type,e.source,e.target]));
}
NODE"

